// RFC 3492 punycode encoding (encode only).

const BASE = 36;
const TMIN = 1;
const TMAX = 26;
const SKEW = 38;
const DAMP = 700;
const INITIAL_BIAS = 72;
const INITIAL_N = 128;
const DELIMITER = '-';

function digitToBasic(d) {
  // 0..25 -> a..z, 26..35 -> 0..9
  return String.fromCharCode(d < 26 ? 97 + d : 48 + (d - 26));
}

function adapt(delta, numPoints, firstTime) {
  delta = firstTime ? Math.floor(delta / DAMP) : delta >> 1;
  delta += Math.floor(delta / numPoints);
  let k = 0;
  while (delta > Math.floor(((BASE - TMIN) * TMAX) / 2)) {
    delta = Math.floor(delta / (BASE - TMIN));
    k += BASE;
  }
  return k + Math.floor(((BASE - TMIN + 1) * delta) / (delta + SKEW));
}

export function punycodeEncode(str) {
  const input = Array.from(str, (ch) => ch.codePointAt(0));
  const n = INITIAL_N;
  let delta = 0;
  let bias = INITIAL_BIAS;
  const output = [];

  // Copy basic code points.
  for (const c of input) {
    if (c < 0x80) output.push(String.fromCharCode(c));
  }

  const b = output.length;
  let h = b;
  if (b > 0) output.push(DELIMITER);

  let curN = n;
  while (h < input.length) {
    // Find the next smallest code point >= curN.
    let m = Infinity;
    for (const c of input) {
      if (c >= curN && c < m) m = c;
    }

    delta += (m - curN) * (h + 1);
    curN = m;

    for (const c of input) {
      if (c < curN) {
        delta += 1;
      } else if (c === curN) {
        let q = delta;
        for (let k = BASE; ; k += BASE) {
          const t = k <= bias ? TMIN : k >= bias + TMAX ? TMAX : k - bias;
          if (q < t) break;
          output.push(digitToBasic(t + ((q - t) % (BASE - t))));
          q = Math.floor((q - t) / (BASE - t));
        }
        output.push(digitToBasic(q));
        bias = adapt(delta, h + 1, h === b);
        delta = 0;
        h += 1;
      }
    }

    delta += 1;
    curN += 1;
  }

  return output.join('');
}

