import { punycodeEncode } from './punycode.mjs';

// Python encodings.idna-compatible domain-to-ASCII encoding.
export function idnaEncode(domain) {
  const labels = domain.split('.');
  const result = [];
  for (const label of labels) {
    let out;
    if (label === '') {
      out = label; // keep empty labels as-is (e.g. trailing dot)
    } else if ([...label].every((ch) => ch.codePointAt(0) < 128)) {
      out = label;
    } else {
      out = 'xn--' + punycodeEncode(label);
    }
    if (out.length > 63) {
      throw new Error('label empty or too long');
    }
    result.push(out);
  }
  return result.join('.');
}

