// furl-style decode-then-re-encode percent normalization for URL components.
// Pure JavaScript, ES Module, zero dependencies.

const HEX = '0123456789ABCDEF';

function isHexDigit(c) {
  const code = c.charCodeAt(0);
  return (code >= 0x30 && code <= 0x39) || // 0-9
    (code >= 0x41 && code <= 0x46) || // A-F
    (code >= 0x61 && code <= 0x66); // a-f
}

function hexValue(c) {
  const code = c.charCodeAt(0);
  if (code >= 0x30 && code <= 0x39) return code - 0x30;
  if (code >= 0x41 && code <= 0x46) return code - 0x41 + 10;
  return code - 0x61 + 10;
}

function hexPair(byte) {
  return '%' + HEX[byte >> 4] + HEX[byte & 0x0f];
}

// Decode-then-re-encode: valid %XX escapes contribute their byte, a '%' not
// followed by two hex digits contributes byte 0x25, ASCII chars contribute
// their char code, and non-ASCII chars contribute their UTF-8 bytes.
function normalize(s, safe, quotePlus) {
  const bytes = [];
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    const code = ch.charCodeAt(0);
    if (ch === '%') {
      if (i + 2 < s.length && isHexDigit(s[i + 1]) && isHexDigit(s[i + 2])) {
        bytes.push((hexValue(s[i + 1]) << 4) | hexValue(s[i + 2]));
        i += 2;
      } else {
        bytes.push(0x25);
      }
    } else if (quotePlus && ch === '+') {
      bytes.push(0x20); // quote_plus: raw '+' decodes to space
    } else if (code < 0x80) {
      bytes.push(code);
    } else {
      // Encode the full code point (handles surrogate pairs) as UTF-8.
      const cp = ch.codePointAt(0);
      if (cp > 0xffff) i++; // consume the low surrogate
      if (cp < 0x800) {
        bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
      } else if (cp < 0x10000) {
        bytes.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
      } else {
        bytes.push(
          0xf0 | (cp >> 18),
          0x80 | ((cp >> 12) & 0x3f),
          0x80 | ((cp >> 6) & 0x3f),
          0x80 | (cp & 0x3f)
        );
      }
    }
  }

  let out = '';
  for (const byte of bytes) {
    if (quotePlus && byte === 0x20) {
      out += '+'; // quote_plus: space encodes as '+'
    } else if (byte < 0x80 && safe.has(byte)) {
      out += String.fromCharCode(byte);
    } else {
      out += hexPair(byte);
    }
  }
  return out;
}

function makeSafe(chars) {
  const set = new Set();
  for (const ch of chars) set.add(ch.charCodeAt(0));
  return set;
}

const UNRESERVED = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~';
const SUB_DELIMS = "!$&'()*+,;=";

const SAFE_PATH = makeSafe(UNRESERVED + SUB_DELIMS + ':@/');
const SAFE_USERINFO = makeSafe(UNRESERVED + SUB_DELIMS);
const SAFE_QUERY = makeSafe(UNRESERVED);
const SAFE_FRAGMENT = makeSafe(UNRESERVED + SUB_DELIMS + ':@/?');

export function encodePath(s) {
  return normalize(s, SAFE_PATH, false);
}

export function encodeUserinfo(s) {
  return normalize(s, SAFE_USERINFO, false);
}

export function encodeQueryComponent(s) {
  return normalize(s, SAFE_QUERY, true);
}

export function encodeFragment(s) {
  return normalize(s, SAFE_FRAGMENT, false);
}

