/**
 * furl-compatible URL splitter.
 *
 * Splits a URL string into {scheme, netloc, path, query, fragment}.
 * scheme is a lowercased string or null, netloc is a string or null,
 * path/query/fragment are strings (possibly empty).
 */
export function urlsplit(url) {
  // 1. Remove ALL tab, carriage return and newline characters.
  url = url.replace(/[\t\r\n]/g, '');

  // 2. fragment = substring after the FIRST '#', url = before it.
  let fragment = '';
  const hashIdx = url.indexOf('#');
  if (hashIdx !== -1) {
    fragment = url.slice(hashIdx + 1);
    url = url.slice(0, hashIdx);
  }

  // 3. query = substring after the FIRST '?', url = before it.
  let query = '';
  const qIdx = url.indexOf('?');
  if (qIdx !== -1) {
    query = url.slice(qIdx + 1);
    url = url.slice(0, qIdx);
  }

  // 4. scheme: optional scheme part (if present and non-empty must start
  //    with an ASCII letter and contain no '/' or ':'), followed by ':'.
  //    An empty scheme before the colon is allowed.
  let scheme = null;
  let rest = url;
  const m = /^(?:([A-Za-z][^/:]*)?):(.*)$/s.exec(url);
  if (m !== null) {
    scheme = (m[1] || '').toLowerCase();
    rest = m[2];
  }

  // 5. If rest starts with '//': netloc up to the next '/' (backslash
  //    does NOT terminate the netloc); otherwise netloc is null.
  let netloc = null;
  let path;
  if (rest.startsWith('//')) {
    const afterSlashes = rest.slice(2);
    const slashIdx = afterSlashes.indexOf('/');
    if (slashIdx === -1) {
      netloc = afterSlashes;
      path = '';
    } else {
      netloc = afterSlashes.slice(0, slashIdx);
      path = afterSlashes.slice(slashIdx);
    }
  } else {
    path = rest;
  }

  return { scheme, netloc, path, query, fragment };
}

