/**
 * furl-compatible host and port validation.
 */

const FORBIDDEN_HOST_CHARS = "!@#$%^&'\"*()+=:;/";

/**
 * Validate a host string. Throws an Error when invalid, returns undefined
 * when valid.
 */
export function validateHost(host) {
  // '' is valid.
  if (host === '') {
    return;
  }

  // Bracketed (IPv6-style) hosts.
  if (host.includes('[') || host.includes(']')) {
    const m = /^\[([^\]]*)\](.*)$/s.exec(host);
    if (m === null) {
      throw new Error('Invalid IPv6 URL');
    }
    if (m[1] === '') {
      throw new Error("'' does not appear to be an IPv4 or IPv6 address");
    }
    if (m[2] !== '') {
      // Recursively apply the normal rules to the remainder. The
      // bracketed content itself is exempt from all character checks.
      validateHost(m[2]);
    }
    return;
  }

  const invalid =
    // Must contain at least one non-period character.
    !/[^.]/.test(host) ||
    // Must not contain any forbidden character.
    [...FORBIDDEN_HOST_CHARS].some((ch) => host.includes(ch)) ||
    // Every label except possibly the last must be non-empty (rejects
    // 'a..b', '.com', '..', '...' but allows trailing dot 'host.').
    host.split('.').slice(0, -1).some((label) => label === '');

  if (invalid) {
    throw new Error(
      `Invalid host '${host}'. Host strings must have at least one ` +
        `non-period character, can't contain any of ` +
        `'!@#$%^&\\'"*()+=:;/', and can't have adjacent periods.`
    );
  }
}

/**
 * Parse and validate a raw port substring from a netloc. Returns the
 * integer port value, or throws an Error when invalid.
 */
export function parsePort(str) {
  if (str === '' || !/^[0-9]+$/.test(str)) {
    throw new Error(`Invalid port '${str}'.`);
  }
  const port = parseInt(str, 10);
  if (port < 1 || port > 65535) {
    throw new Error(`Invalid port '${str}'.`);
  }
  return port;
}

