args.command:
cat > /tmp/selftest.mjs <<'EOF'
import { urlsplit } from '/output/lib/urlsplit.mjs';
import { validateHost, parsePort } from '/output/lib/host.mjs';
import assert from 'node:assert/strict';

// urlsplit
assert.deepEqual(urlsplit('http://EX.com:80/p?x#f'),
  { scheme: 'http', netloc: 'EX.com:80', path: '/p', query: 'x', fragment: 'f' });
assert.deepEqual(urlsplit('example.com/p'),
  { scheme: null, netloc: null, path: 'example.com/p', query: '', fragment: '' });
assert.deepEqual(urlsplit('//ex.com/p'),
  { scheme: null, netloc: 'ex.com', path: '/p', query: '', fragment: '' });
assert.deepEqual(urlsplit('::1'),
  { scheme: '', netloc: null, path: ':1', query: '', fragment: '' });
assert.deepEqual(urlsplit('a b:c d'),
  { scheme: 'a b', netloc: null, path: 'c d', query: '', fragment: '' });
assert.deepEqual(urlsplit('http://h\\p'),
  { scheme: 'http', netloc: 'h\\p', path: '', query: '', fragment: '' });
assert.deepEqual(urlsplit('http:example.com'),
  { scheme: 'http', netloc: null, path: 'example.com', query: '', fragment: '' });
assert.deepEqual(urlsplit(''),
  { scheme: null, netloc: null, path: '', query: '', fragment: '' });
assert.deepEqual(urlsplit('ht tp://x'),
  { scheme: 'ht tp', netloc: 'x', path: '', query: '', fragment: '' });
assert.deepEqual(urlsplit(':x'),
  { scheme: '', netloc: null, path: 'x', query: '', fragment: '' });
assert.deepEqual(urlsplit('a/b:c'),
  { scheme: null, netloc: null, path: 'a/b:c', query: '', fragment: '' });
assert.deepEqual(urlsplit('1abc://h'),
  { scheme: null, netloc: null, path: '1abc://h', query: '', fragment: '' });
assert.deepEqual(urlsplit('+foo:h'),
  { scheme: null, netloc: null, path: '+foo:h', query: '', fragment: '' });
assert.deepEqual(urlsplit('ht\ttp\r:\r\n//x\n/p\t'),
  { scheme: 'http', netloc: 'x', path: '/p', query: '', fragment: '' });

// validateHost - valid cases
validateHost('');
validateHost('a.com.');
validateHost('a_b.com');
validateHost('ho st.com');
validateHost('[::1]');
validateHost('[2001:db8::1%25eth0]');

