// Emulation of:
//   parser = argparse.ArgumentParser()
//   parser.add_argument('--a', type=str, required=True)
//   parser.add_argument('--b', type=str, required=True)
import process from 'node:process';

const LONG_OPTIONS = ['--help', '--a', '--b'];

// argparse's negative-number matcher: tokens like '-1' or '-.5' are values,
// not options (the parser defines no option that looks like a number).
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B`;
}

function helpText(prog) {
  return [
    usageLine(prog),
    '',
    'options:',
    '  -h, --help  show this help message and exit',
    '  --a A',
    '  --b B',
  ].join('\n') + '\n';
}

function printHelpAndExit(prog) {
  process.stdout.write(helpText(prog));
  process.exit(0);
}

function errorAndExit(prog, message) {
  process.stderr.write(usageLine(prog) + '\n');
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

// A token is option-like (and thus refused as a space-form value) when it
// starts with '-', is more than just '-', and is not a negative number.
function looksLikeOption(token) {
  if (token.length < 2 || !token.startsWith('-')) return false;
  return !NEGATIVE_NUMBER.test(token);
}

// Resolve a long-option name (the part before any '='). Exact match wins;
// otherwise an unambiguous prefix of exactly one defined long option matches.
function matchLongOption(name) {
  if (LONG_OPTIONS.includes(name)) return name;
  const matches = LONG_OPTIONS.filter((opt) => opt.startsWith(name));
  if (matches.length === 1) return matches[0];
  return null;
}

export function parseArgs(argv, prog) {
  const values = {};
  const extras = [];
  let optionsEnded = false;
  let i = 0;

  while (i < argv.length) {
    const token = argv[i];

    if (optionsEnded) {
      extras.push(token);
      i += 1;
      continue;
    }

    if (token === '--') {
      optionsEnded = true;
      i += 1;
      continue;
    }

    if (token === '-h') {
      printHelpAndExit(prog);
    }

    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      const name = eq === -1 ? token : token.slice(0, eq);
      const explicitValue = eq === -1 ? undefined : token.slice(eq + 1);
      const matched = matchLongOption(name);

      if (matched === null) {
        extras.push(token);
        i += 1;
        continue;
      }

      if (matched === '--help') {
        printHelpAndExit(prog);
      }

      const key = matched === '--a' ? 'a' : 'b';
      if (explicitValue !== undefined) {
        // Equals form: value is taken verbatim, even when empty.
        values[key] = explicitValue;
        i += 1;
      } else {
        const next = argv[i + 1];
        if (next === undefined || looksLikeOption(next)) {
          errorAndExit(prog, `argument ${matched}: expected one argument`);
        }
        values[key] = next;
        i += 2;
      }
      continue;
    }

    // Single-dash options, negative numbers, and stray positionals: all extras.
    extras.push(token);
    i += 1;
  }

  const missing = [];
  if (!('a' in values)) missing.push('--a');
  if (!('b' in values')) missing.push('--b');
  if (missing.length > 0) {
    errorAndExit(prog, `the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    errorAndExit(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return { a: values.a, b: values.b };
}

