import { spawnSync } from 'node:child_process';

const PROG = 'apg_driver.mjs';
const USAGE = `usage: ${PROG} [-h] --a A --b B`;
const HELP = [
  USAGE,
  '',
  'options:',
  '  -h, --help  show this help message and exit',
  '  --a A',
  '  --b B',
  '',
].join('\n');

function errOut(msg) {
  return `${USAGE}\n${PROG}: error: ${msg}\n`;
}

const cases = [
  { args: [], code: 2, stderr: errOut('the following arguments are required: --a, --b'), stdout: '' },
  { args: ['--a', 'x'], code: 2, stderr: errOut('the following arguments are required: --b'), stdout: '' },
  { args: ['--a', 'x', '--b', 'y', '--extra', 'foo'], code: 2, stderr: errOut('unrecognized arguments: --extra foo'), stdout: '' },
  { args: ['--a', '-x', '--b', 'y'], code: 2, stderr: errOut('argument --a: expected one argument'), stdout: '' },
