// The path is split on '/', each segment is encoded with a safe set that
// excludes '/', and the segments are rejoined with '/'. Raw '/' is thus a
// preserved separator while an escaped %2F decodes to a '/' byte inside a
// segment and is re-emitted as %2F; escapes of other safe reserved chars
// decode to their literal character (e.g. %3B -> ';').
export function encodePath(s) {
  return s
    .split('/')
    .map((segment) => normalize(segment, SAFE_PATH_SEGMENT, false, SAFE_PATH_SEGMENT))
    .join('/');
}

// Userinfo safe set is unreserved ONLY: '!' -> %21, ':' -> %3A, '@' -> %40.
export function encodeUserinfo(s) {
  return normalize(s, SAFE_UNRESERVED, false);
}

