// furl-compatible URL manipulation: Furl class with the observed behavior of
// furl.furl(url).set(host=...).url. Pure JavaScript, ES Module.
import { urlsplit } from './urlsplit.mjs';
import { validateHost, parsePort } from './host.mjs';
import { idnaEncode } from './idna.mjs';
import {
  encodePath,
  encodeUserinfo,
  encodeQueryComponent,
  encodeFragment,
} from './percent.mjs';

// Scheme -> default port. A port equal to the scheme's default is stripped.
const DEFAULT_PORTS = {
  http: 80,
  https: 443,
  ws: 80,
  wss: 443,
  ftp: 21,
  ssh: 22,
  telnet: 23,
  smtp: 25,
  pop3: 110,
  imap: 143,
  nntp: 119,
  gopher: 70,
  ldap: 389,
};

export class Furl {
  constructor(url) {
    const parts = urlsplit(url);
    this.scheme = parts.scheme; // string (possibly ''), or null
    this.host = null;
    this.port = null;
    this.hasUserinfo = false;
    this.username = null;
    this.password = null;

    if (parts.netloc !== null) {
      let hostport = parts.netloc;

      if (hostport.includes('@')) {
        // Split at the LAST '@' -> userinfo, hostport.
        const at = hostport.lastIndexOf('@');
        const userinfo = hostport.slice(0, at);
        hostport = hostport.slice(at + 1);
        this.hasUserinfo = true;
        // Split userinfo at the FIRST ':' -> username, password.
        const colon = userinfo.indexOf(':');
        if (colon === -1) {
          this.username = userinfo;
          this.password = null;
        } else {
          this.username = userinfo.slice(0, colon);
          this.password = userinfo.slice(colon + 1);
        }
      }

      let host;
      let port;
      if (hostport.startsWith('[')) {
        const end = hostport.indexOf(']');
        if (end === -1) {
          throw new Error('Invalid IPv6 URL');
        }
        host = hostport.slice(0, end + 1);
        const rest = hostport.slice(end + 1);
        if (rest === '') {
          port = null;
        } else if (rest.startsWith(':')) {
          port = parsePort(rest.slice(1));
        } else {
          // Produces the exact Invalid host message by throwing.
          validateHost(hostport);
        }
      } else {
        const idx = hostport.lastIndexOf(':');
        if (idx !== -1) {
          host = hostport.slice(0, idx);
          port = parsePort(hostport.slice(idx + 1));
        } else {
          host = hostport;
          port = null;
        }
      }

      validateHost(host);
      this.host = host.toLowerCase();

      // Default-port stripping (':080' parses to 80 and strips for http).
      if (
        port !== null &&
        this.scheme !== null &&
        DEFAULT_PORTS[this.scheme] === port
      ) {
        port = null;
      }
      this.port = port;
    }

    this.path = parts.path;
    this.query = parts.query;
    this.fragment = parts.fragment;
  }

  set({ host } = {}) {
    if (host !== undefined) {
      validateHost(host);
      this.host = host.toLowerCase();
    }
    return this;
  }

  get url() {
    let s = (this.scheme !== null ? this.scheme + ':' : '') + '//';

    if (this.hasUserinfo) {
      s += encodeUserinfo(this.username);
      if (this.password !== null) {
        s += ':' + encodeUserinfo(this.password);
      }
      s += '@';
    }

    if (this.host !== null && this.host !== '') {
      // Bracketed IPv6 hosts are ASCII and pass through idnaEncode
      // unchanged; emit them verbatim to be safe.
      s += this.host.startsWith('[') ? this.host : idnaEncode(this.host);
    }

    if (this.port !== null) {
      s += ':' + this.port;
    }

    if (this.path !== '') {
      let p = encodePath(this.path);
      if (!p.startsWith('/')) {
        p = '/' + p;
      }
      s += p;
    }

    if (this.query !== '') {
      const pieces = this.query.split('&').map((piece) => {
        const eq = piece.indexOf('=');
        if (eq === -1) {
          return encodeQueryComponent(piece);
        }
        return (
          encodeQueryComponent(piece.slice(0, eq)) +
          '=' +
          encodeQueryComponent(piece.slice(eq + 1))
        );
      });
      s += '?' + pieces.join('&');
    }

    if (this.fragment !== '') {
      s += '#' + encodeFragment(this.fragment);
    }

    return s;
  }
}

