import process from 'node:process';
import { basename } from 'node:path';
import { parseArgs } from './lib/argparse.mjs';
import { Furl } from './lib/furl.mjs';

const args = parseArgs(process.argv.slice(2), basename(process.argv[1]));

try {
  const f = new Furl(args.a);
  console.log(f.set({ host: args.b }).url);
} catch (e) {
  process.stderr.write('ValueError: ' + e.message + '\n');
  process.exit(1);
}

