// Compares stdout and exit code. For exit-1 cases, also requires our stderr
// to be non-empty. Stderr text is NOT compared (Python traceback vs ours,
// and argparse prog-name differences are expected).
import { execFileSync } from 'node:child_process';

const REF = '/workspace/dataset/test2_executable';
const OURS = '/output/test2.mjs';

function runRef(argv) {
  try {
    const stdout = execFileSync(REF, argv, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
    return { code: 0, stdout };
  } catch (e) {
    return { code: e.status ?? -1, stdout: e.stdout?.toString() ?? '' };
  }
}

function runOurs(argv) {
  try {
    const stdout = execFileSync('node', [OURS, ...argv], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
    return { code: 0, stdout, stderr: '' };
  } catch (e) {
    return { code: e.status ?? -1, stdout: e.stdout?.toString() ?? '', stderr: e.stderr?.toString() ?? '' };
  }
}

const cases = [];
const ab = (a, b) => cases.push(['--a', a, '--b', b]);

// basics
ab('http://example.com/path?x=1#frag', 'newhost.com');
ab('HTTP://EXAMPLE.COM/P', 'NEW.COM');
// ports
for (const a of ['http://a.com:80/p', 'https://a.com:443/p', 'http://a.com:8080/p',
  'http://a.com:080/p', 'ftp://h:21/p', 'http://a.com:443/p']) ab(a, 'b.com');
// schemes / odd inputs
for (const a of ['', 'http:', 'http://', '//', ':', '::1', 'example.com/p',
  '//example.com/p', 'http:example.com', 'http:///p', 'mailto:x@y', 'file:///p',
  'a b:c d', 'ht tp://x', '1abc://h/p', '+foo://h', 'a/b:c']) {
  ab(a, 'h.com');
}
for (const a of ['', 'http:', 'http://', '//example.com/p', 'http:///p', 'mailto:x@y', 'file:///p']) ab(a, '');
// userinfo
for (const a of ['http://user:pass@example.com:8080/p', 'http://user@example.com/',
  'http://@example.com/p', 'http://user:p:a:ss@example.com/p',
  'http://user:p%40ss@example.com/p', 'http://user%3Aname@h/p',
  'http://user%21name@h/p']) ab(a, 'newhost.com');
// ipv6
ab('http://[::1]:8080/p', 'example.com');
ab('http://[::1]:8080/p', '[2001:db8::1]');
ab('http://[::1]:8080/p', '');
// paths
for (const p of ['/a b', '/a%2fb%2Fc', '/a%3Bb', '/a%zz', '/%2', '/é?q=中文',
  '/a/./b/../c', '//a//b', '/p\\q', '/a;b=1/c', '/a+b']) ab('http://h' + p, 'n');
// queries
for (const q of ['?x', '?x=', '?', '?&&', '?=v', '?q=a b', '?q=a+b', '?q=a%2Bb',
  '?a%20b=c', '?x=1;y=2', '?x=1;y=2&z=3', '?q=a/b?c']) ab('http://h/p' + q, 'n');
// fragments
for (const f of ['#f g', '#f#g', '#a/b?c=d', '#', '#f%2fg', '#f%21g']) ab('http://h/p' + f, 'n');
// unicode hosts
ab('http://münchen.de/p', 'bücher.de');
ab('http://münchen.de/p', '主机.com');
ab('http://münchen.de/p', 'xn--mnchen-3ya.de');
ab('http://münchen.de/p', 'a.com.');
ab('http://münchen.de/p', 'B.COM.');
// error cases (expect exit 1 both sides)
for (const a of ['http://a.com:0/p', 'http://x:notaport/p', 'http://x:99999/p',
  'http://h:/p', 'http://[badipv6/', 'http://us@er@example.com/p']) ab(a, 'h.com');
for (const b of ['user@h.com', 'h.com:99', 'a/b', 'a..b', '.com', '...', '::1',
  '[::1', '[]', '[::1]:9090', '%zz',
  'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.com']) {
  ab('http://h/p', b);
}
// degenerate
ab('http://user@:8080/', 'h.com');
ab('http://user@:8080/', '');
ab('http://:8080/', 'h.com');
ab('/path/only', '');
ab('?q=1', 'h.com');
ab('#frag', '');
ab('http://example.com/', '');
ab('http://h/p', 'ho st.com');
ab('http://h/p', ' h.com ');
// argparse cases (arrays passed verbatim)
cases.push([]);
cases.push(['--a', 'x']);
cases.push(['--a', 'x', '--b', 'y', '--unknown']);
cases.push(['--a', '-x', '--b', 'y']);
cases.push(['--a', '-1', '--b', 'y']);
cases.push(['--a=-x', '--b', 'y']);
cases.push(['--a', 'x', '--a', 'y', '--b', 'z']);
cases.push(['--help']);

let pass = 0;
let fail = 0;
for (const argv of cases) {
  const r = runRef(argv);
  const o = runOurs(argv);
  const problems = [];
  if (r.code !== o.code) problems.push(`exit ${o.code} != ref ${r.code}`);
  if (r.stdout !== o.stdout) problems.push(`stdout ${JSON.stringify(o.stdout)} != ref ${JSON.stringify(r.stdout)}`);
  if (o.code === 1 && !(o.stderr && o.stderr.length > 0)) problems.push('exit 1 but empty stderr');
  if (problems.length > 0) {
    fail++;
    console.log('FAIL', JSON.stringify(argv));
    for (const p of problems) console.log('     ', p);
  } else {
    pass++;
  }
}
console.log(`\n${pass} passed, ${fail} failed, ${cases.length} total`);
process.exit(fail === 0 ? 0 : 1);
